function main(): void {
  const ia = new Int32Array(new SharedArrayBuffer(16));
  const out: any[] = [];
  const keep = setInterval(() => {}, 50);
  (async () => {
    const r: any = Atomics.waitAsync(ia, 0, 0, 5);
    out.push(await r.value);
    out.push(Atomics.notify(ia, 0));
    const r2: any = Atomics.waitAsync(ia, 0, 0, 1000);
    out.push(Atomics.notify(ia, 0, 1), await r2.value);
    clearInterval(keep);
    console.log(JSON.stringify(out));
  })();
}
